using System.Diagnostics;
using System.IO.Compression;
using System.Text.Json;
using LaunchDesk.Core;
using SeaGendManager;

var root=Path.Combine(Path.GetTempPath(),"LaunchDesk-fusion-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Store.Configure(Path.Combine(root,"records"));
int passed=0;var failures=new List<string>();
void Check(bool value,string message){if(!value)throw new Exception(message);}
void Reject(Action action){try{action();}catch(Exception ex)when(ex is IOException or InvalidDataException or ArgumentException or InvalidOperationException){return;}throw new Exception("Expected rejection");}
async Task Test(string name,Func<Task> run){try{await run();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failures.Add(name+": "+ex.Message);Console.WriteLine("FAIL "+name+": "+ex);}}
string NewDir(string name){var path=Path.Combine(root,Guid.NewGuid().ToString("N"),name);Directory.CreateDirectory(path);return path;}
Plan Folder(string source,string target,bool keep=true)=>new(){Id=Guid.NewGuid().ToString("N"),SourceKind=ToolSourceKind.Folder,Source=source,Target=target,DataRoot=Store.DataRoot,KeepBackup=keep,ToolId="test-tool",ToolName="PML AI"};
var source=NewDir("source 中文");await File.WriteAllTextAsync(Path.Combine(source,"a.pmlfnc"),"new content");Directory.CreateDirectory(Path.Combine(source,"Forms"));await File.WriteAllTextAsync(Path.Combine(source,"Forms","中文.pmlfrm"),"new form");
await Test("Folder preview is read-only; nested files deploy and rollback",()=>{var target=NewDir("PMLAI");File.WriteAllText(Path.Combine(target,"a.pmlfnc"),"original");var plan=Folder(source,target);Check(Engine.Preview(plan).Count==2,"preview count");Check(File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="original","preview wrote target");var r=Engine.Apply(plan,null);Check(r.Status=="Success"&&r.BackupFiles==1&&r.Files.Count==2,"deploy counts");Check(File.ReadAllText(Path.Combine(target,"Forms","中文.pmlfrm"))=="new form","nested form");Engine.Rollback(target,r.Id);Check(File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="original"&&!Directory.Exists(Path.Combine(target,"Forms")),"rollback incomplete");return Task.CompletedTask;});
await Test("Identical files are skipped with timestamp preserved",()=>{var target=NewDir("PMLAI");var r=Engine.Apply(Folder(source,target,false),null);var file=Path.Combine(target,"a.pmlfnc");var time=File.GetLastWriteTimeUtc(file);using(var held=File.Open(file,FileMode.Open,FileAccess.Read,FileShare.Read)){var same=Engine.Apply(Folder(source,target,true),null);Check(same.Status=="NoChanges"&&same.SkippedFiles==2,"same file changed");}Check(File.GetLastWriteTimeUtc(file)==time,"timestamp changed");Check(!File.Exists(Path.Combine(Store.Transaction(target,r.Id),"rollback.zip")),"default retained backup");Reject(()=>Engine.Rollback(target,r.Id));return Task.CompletedTask;});
await Test("Multiple loose files keep edited relative mappings",()=>{var target=NewDir("OtherTool");var plan=Folder(source,target);plan.SourceKind=ToolSourceKind.Files;plan.Source=Path.Combine(source,"a.pmlfnc");plan.SourceFiles=[new(){SourcePath=plan.Source,RelativePath="Functions/chat.pmlfnc"},new(){SourcePath=Path.Combine(source,"Forms","中文.pmlfrm"),RelativePath="UI/ai.pmlfrm"}];var r=Engine.Apply(plan,null);Check(r.Status=="Success"&&File.Exists(Path.Combine(target,"Functions","chat.pmlfnc"))&&File.Exists(Path.Combine(target,"UI","ai.pmlfrm")),"mapping missing");Engine.Rollback(target,r.Id);Check(!Directory.Exists(Path.Combine(target,"UI")),"added directories remained");return Task.CompletedTask;});
await Test("ZIP packages flatten a matching custom outer folder",()=>{var zipRoot=NewDir("package");Directory.CreateDirectory(Path.Combine(zipRoot,"MyAI"));File.WriteAllText(Path.Combine(zipRoot,"MyAI","ai.pmlfnc"),"zip content");var zip=Path.Combine(root,"MyAI.zip");ZipFile.CreateFromDirectory(zipRoot,zip);var target=NewDir("MyAI");var plan=Folder(source,target);plan.SourceKind=ToolSourceKind.Archive;plan.Source=zip;plan.Flatten=true;var r=Engine.Apply(plan,null);Check(r.Status=="Success"&&r.Flattened&&File.ReadAllText(Path.Combine(target,"ai.pmlfnc"))=="zip content","generic flatten failed");return Task.CompletedTask;});
await Test("7z source and nonmatching outer folder preserve structure",()=>{var pkg=NewDir("Pack");File.WriteAllText(Path.Combine(pkg,"a.txt"),"7z content");var archive=Path.Combine(root,"native.7z");Engine.Run7z("a -t7z -y -- "+Engine.Quote(archive)+" "+Engine.Quote(pkg),null);var target=NewDir("DifferentName");var p=Folder(source,target);p.SourceKind=ToolSourceKind.Archive;p.Source=archive;p.Flatten=true;var r=Engine.Apply(p,null);Check(r.Status=="Success"&&!r.Flattened&&File.Exists(Path.Combine(target,"Pack","a.txt")),"7z import failed");return Task.CompletedTask;});
await Test("ZIP traversal and duplicate mapping reject before target writes",()=>{var zip=Path.Combine(root,"escape.zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create)){using var w=new StreamWriter(z.CreateEntry("../escape.pmlfnc").Open());w.Write("bad");}var target=NewDir("Target");var p=Folder(source,target);p.SourceKind=ToolSourceKind.Archive;p.Source=zip;Reject(()=>Engine.Preview(p));Check(!File.Exists(Path.Combine(root,"escape.pmlfnc")),"escaped");p=Folder(source,target);p.SourceKind=ToolSourceKind.Files;p.Source=Path.Combine(source,"a.pmlfnc");p.SourceFiles=[new(){SourcePath=p.Source,RelativePath="same.pmlfnc"},new(){SourcePath=p.Source,RelativePath="SAME.pmlfnc"}];Reject(()=>Engine.Preview(p));return Task.CompletedTask;});
await Test("Source-target overlap and unsafe mapping reject",()=>{var p=Folder(source,Path.Combine(source,"Target"));Reject(()=>Engine.Preview(p));var target=NewDir("Target");p=Folder(source,target);p.SourceKind=ToolSourceKind.Files;p.Source=Path.Combine(source,"a.pmlfnc");p.SourceFiles=[new(){SourcePath=p.Source,RelativePath="..\\escape"}];Reject(()=>Engine.Preview(p));return Task.CompletedTask;});
await Test("Partial failure automatically restores without retained backup",()=>{var target=NewDir("PMLAI");File.WriteAllText(Path.Combine(target,"a.pmlfnc"),"before failure");bool injected=false;var r=Engine.Apply(Folder(source,target,false),message=>{if(!injected&&message.StartsWith("写入文件 1")){injected=true;throw new IOException("Injected failure");}});Check(injected&&r.Status=="FailedRolledBack"&&File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="before failure","automatic restore failed");Check(!File.Exists(Path.Combine(target,"Forms","中文.pmlfrm")),"added form remains");return Task.CompletedTask;});
await Test("Modified deployed file blocks rollback before overwrites",()=>{var target=NewDir("PMLAI");File.WriteAllText(Path.Combine(target,"a.pmlfnc"),"original");var r=Engine.Apply(Folder(source,target),null);File.WriteAllText(Path.Combine(target,"a.pmlfnc"),"personal edit");Reject(()=>Engine.Rollback(target,r.Id));Check(File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="personal edit","edit overwritten");return Task.CompletedTask;});
await Test("Only latest successful update can be rolled back",()=>{var target=NewDir("PMLAI");var first=Engine.Apply(Folder(source,target),null);var nextSource=NewDir("next");File.WriteAllText(Path.Combine(nextSource,"a.pmlfnc"),"next");var second=Engine.Apply(Folder(nextSource,target),null);Reject(()=>Engine.Rollback(target,first.Id));Engine.Rollback(target,second.Id);Check(File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="new content","latest restore failed");return Task.CompletedTask;});
await Test("Corrupt backup rejects restore and leaves deployed data intact",()=>{var target=NewDir("PMLAI");File.WriteAllText(Path.Combine(target,"a.pmlfnc"),"before");var r=Engine.Apply(Folder(source,target),null);File.AppendAllText(Path.Combine(Store.Transaction(target,r.Id),"rollback.zip"),"tamper");Reject(()=>Engine.Rollback(target,r.Id));Check(File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="new content","tampered rollback wrote data");return Task.CompletedTask;});
await Test("Interrupted journal is recovered and blocks subsequent deploy",()=>{var target=NewDir("PMLAI");File.WriteAllText(Path.Combine(target,"a.pmlfnc"),"before");var r=Engine.Apply(Folder(source,target),null);r.Status="Applying";var tx=Store.Transaction(target,r.Id);Store.Save(Path.Combine(tx,"receipt.json"),r);Reject(()=>Engine.Apply(Folder(source,target),null));Engine.Rollback(target,r.Id);Check(File.ReadAllText(Path.Combine(target,"a.pmlfnc"))=="before","interrupted recovery failed");return Task.CompletedTask;});
await Test("Process variables resolve target/references without changing parent",()=>{var t=new ToolEntry{Name="AI",TargetDirectory=source,Variables=[new(){Name="PmlAiRoot",Value="{Target}"},new(){Name="PmlAiForms",Value="%PmlAiRoot%\\Forms"}]};var before=Environment.GetEnvironmentVariable("PmlAiRoot");var start=new ProcessStartInfo();ToolEnvironment.ApplyToStart(start,[t]);Check(start.Environment["PmlAiForms"]==source+"\\Forms","reference expansion");Check(Environment.GetEnvironmentVariable("PmlAiRoot")==before,"parent changed");return Task.CompletedTask;});
await Test("Conflicting variables and cyclic references reject",()=>{var a=new ToolEntry{Variables=[new(){Name="Root",Value="A"}]};var b=new ToolEntry{Variables=[new(){Name="Root",Value="B"}]};Reject(()=>ToolEnvironment.Resolve([a,b]));a.Variables=[new(){Name="A",Value="%B%"},new(){Name="B",Value="%A%"}];Reject(()=>ToolEnvironment.Resolve([a]));Reject(()=>ToolEnvironment.ValidateVariable(new(){Name="AVEVA_LICENSE_SERVER_LIST"}));return Task.CompletedTask;});
await Test("Variable rename retains value and removes old name only after validation",()=>{var env=new Dictionary<(string,VariableScope),string>{{("OldName",VariableScope.User),"path"}};string? Read(string n,VariableScope s)=>env.GetValueOrDefault((n,s));void Write(string n,string? v,VariableScope s){if(v is null)env.Remove((n,s));else env[(n,s)]=v;}var v=new ToolVariable{Name="NewName",Value="path",Scope=VariableScope.User,WasApplied=true,AppliedName="OldName",AppliedValue="path",AppliedScope=VariableScope.User};var result=VariableEditor.Apply(v,"path",Read,Write);Check(!env.ContainsKey(("OldName",VariableScope.User))&&env[("NewName",VariableScope.User)]=="path"&&result.AppliedName=="NewName","rename failed");return Task.CompletedTask;});
await Test("Variable collision and external edit preserve all existing values",()=>{var env=new Dictionary<(string,VariableScope),string>{{("Old",VariableScope.User),"changed"},{("New",VariableScope.User),"other tool"}};string? Read(string n,VariableScope s)=>env.GetValueOrDefault((n,s));void Write(string n,string? v,VariableScope s){if(v is null)env.Remove((n,s));else env[(n,s)]=v;}var v=new ToolVariable{Name="New",Scope=VariableScope.User,WasApplied=true,AppliedName="Old",AppliedValue="before",AppliedScope=VariableScope.User};Reject(()=>VariableEditor.Apply(v,"wanted",Read,Write));Check(env[("Old",VariableScope.User)]=="changed"&&env[("New",VariableScope.User)]=="other tool","values changed");v.AppliedValue="changed";Reject(()=>VariableEditor.Apply(v,"wanted",Read,Write));return Task.CompletedTask;});
await Test("Rename write failure compensates the new variable",()=>{var env=new Dictionary<string,string>{{"Old","old"}};string? Read(string n,VariableScope _)=>env.GetValueOrDefault(n);void Write(string n,string? v,VariableScope _){if(n=="Old"&&v is null)throw new IOException("denied");if(v is null)env.Remove(n);else env[n]=v;}var v=new ToolVariable{Name="New",Scope=VariableScope.User,WasApplied=true,AppliedName="Old",AppliedValue="old",AppliedScope=VariableScope.User};Reject(()=>VariableEditor.Apply(v,"new",Read,Write));Check(!env.ContainsKey("New")&&env["Old"]=="old","compensation failed");return Task.CompletedTask;});
await Test("Tool export/import strips applied ownership and remaps profile references",async()=>{var t=new ToolEntry{Name="AI",RecordsDirectory="private-local-records",Variables=[new(){Name="AiRoot",WasApplied=true,AppliedName="old",AppliedValue="private-state"}]};var app=new AppEntry();var license=new LicenseEntry();var profile=new LoginProfile{AppId=app.Id,LicenseId=license.Id,ToolIds=[t.Id]};var workspace=new Workspace{Tools=[t],Applications=[app],Licenses=[license],Profiles=[profile]};var path=Path.Combine(root,"export.json");await WorkspaceStore.ExportAsync(workspace,[profile.Id],path);var exported=await WorkspaceStore.ReadFileAsync(path);Check(exported.Tools.Count==1&&!exported.Tools[0].Variables[0].WasApplied&&exported.Tools[0].RecordsDirectory=="","machine state leaked");var merged=WorkspaceStore.Merge(workspace,exported);Check(merged.Tools.Count==2&&merged.Profiles[1].ToolIds.Single()==merged.Tools[1].Id&&merged.Profiles[1].ToolIds.Single()!=t.Id,"reference not remapped");await WorkspaceStore.ExportAsync(workspace,[profile.Id],path,false);var noTools=await WorkspaceStore.ReadFileAsync(path);Check(noTools.Tools.Count==0&&noTools.Profiles[0].ToolIds.Count==0,"opt-out ignored");});
await Test("Legacy v1 workspace and legacy receipt JSON remain readable",async()=>{var path=Path.Combine(root,"old.json");await File.WriteAllTextAsync(path,"{\"SchemaVersion\":1,\"Applications\":[],\"Licenses\":[],\"Profiles\":[],\"SearchRoots\":[]}");var w=await new WorkspaceStore(path).LoadAsync();Check(w!.Tools.Count==0,"legacy config");var rp=Path.Combine(root,"receipt.json");await File.WriteAllTextAsync(rp,"{\"Schema\":2,\"Id\":\"legacy\",\"Status\":\"Success\",\"Files\":[],\"CreatedDirectories\":[]}");Check(Store.LoadReceipt(rp).Status=="Success","legacy serialization");});
await Test("Corrupt receipt blocks history without overwriting data",()=>{var target=NewDir("BadHistory");var tx=Store.Transaction(target,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(tx);var path=Path.Combine(tx,"receipt.json");File.WriteAllText(path,"{broken");Reject(()=>Store.History(target));Check(File.ReadAllText(path)=="{broken","bad record changed");return Task.CompletedTask;});
Console.WriteLine($"RESULT {passed} passed, {failures.Count} failed");if(args.Length>0)await File.WriteAllTextAsync(args[0],JsonSerializer.Serialize(new{Passed=passed,Failed=failures.Count,Failures=failures,TestRoot=root},WorkspaceStore.Json));
return failures.Count==0?0:1;
